const box=document.querySelector('#lightbox');document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{box.querySelector('img').src=button.dataset.photo;box.querySelector('img').alt=button.dataset.caption;box.querySelector('p').textContent=button.dataset.caption;box.showModal();}));box.querySelector('.close').addEventListener('click',()=>box.close());box.addEventListener('click',e=>{if(e.target===box)box.close()});